import XCTest

class UITest: XCTestCase {
    var app: XCUIApplication!

    override func setUp() {
        super.setUp()
        continueAfterFailure = false
        app = XCUIApplication()
        app.launch()
    }

    func testNavigateToSettings() {
        // Try to find and tap the menu button (three dots)
        let menuButton = app.buttons.matching(identifier: "settingsButton").firstMatch
        if menuButton.exists {
            menuButton.tap()
        } else {
            // Try finding by accessibility label
            let buttons = app.buttons.allElementsBoundByIndex
            for button in buttons {
                if button.label.contains("menu") || button.label.contains("settings") {
                    button.tap()
                    break
                }
            }
        }

        // Take screenshot for verification
        let screenshot = XCUIScreen.main.screenshot()
        let attachment = XCTAttachment(screenshot: screenshot)
        attachment.name = "SettingsScreen"
        attachment.lifetime = .keepAlways
        add(attachment)
    }
}
